int hasInactiveOrLaterEngines(int *engineStatuses, int totalEngines, int activationTime) {
    for (int i = 0; i < totalEngines; i++) {
        if (engineStatuses[i] == -1 || engineStatuses[i] > activationTime) {
            return 1;  // 发现未激活的引擎，返回1表示"真"
        }
    }
    return 0;  // 所有引擎都已激活，返回0表示"假"
}
